  LinearLayout resultCard=card("结果");root.addView(resultCard);resultBox=col();resultCard.addView(resultBox);LinearLayout rr=row();Button saveBtn=btn("保存当前结果到系统相册",GREEN),shareBtn=btn("分享首图/链接",LINE);rr.addView(saveBtn,weightLp());rr.addView(shareBtn,weightLp());resultCard.addView(rr);saveBtn.setOnClickListener(new View.OnClickListener(){public void onClick(View v){saveResultsToGallery();}});shareBtn.setOnClickListener(new View.OnClickListener(){public void onClick(View v){shareFirst();}});
  LinearLayout histCard=card("历史记录（含缩略图）");root.addView(histCard);historyBox=col();histCard.addView(historyBox);Button clearHist=btn("清空历史和 App 内图片",LINE);histCard.addView(clearHist);clearHist.setOnClickListener(new View.OnClickListener(){public void onClick(View v){clearHistoryAndFiles();}});
